  const push = (i, kind, body) => tokens.push({ line: lineAt[i], col: colAt[i], kind, body })

  // digit run with single underscores between digits; returns new index
  const run = (i, pred) => {
    while (i < n) {
      if (pred(s[i])) i++
      else if (s[i] === '_' && i > 0 && pred(s[i - 1]) && pred(s[i + 1])) i++
      else break
    }
    return i
  }

  let i = 0
  while (i < n) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') { i++; continue }
    if (ch === '/' && s[i + 1] === '/') {
      while (i < n && s[i] !== '\n') i++
      continue
    }
    if (ch === '/' && s[i + 1] === '*') {
      const start = i
      let depth = 1
      i += 2
      while (i < n && depth > 0) {
        if (s[i] === '/' && s[i + 1] === '*') { depth++; i += 2 }
        else if (s[i] === '*' && s[i + 1] === '/') { depth--; i += 2 }
        else i++
      }
      if (depth > 0) return fail(start, 'unterminated block comment')
      continue
    }
    if (ch === 'r' && s[i + 1] === '"') {
      let j = i + 2
      while (j < n && s[j] !== '"') j++
      if (j >= n) return fail(i, 'unterminated string')
      push(i, 'rawstring', JSON.stringify(s.slice(i + 2, j).join('')))
      i = j + 1
      continue
    }
    if (isIdStart(ch)) {
      let j = i + 1
      while (j < n && isIdPart(s[j])) j++
      const w = s.slice(i, j).join('')
      push(i, KEYWORDS.has(w) ? 'keyword' : 'ident', w)
      i = j
      continue
    }
    if (isDigit(ch)) {
      let j = i + 1
      let bad = false
      const p = (s[i + 1] || '').toLowerCase()
      if (ch === '0' && (p === 'x' || p === 'b' || p === 'o')) {
        const pred = p === 'x' ? isHex : p === 'b' ? isBin : isOct
        j = i + 2
        if (!pred(s[j])) bad = true
        else j = run(j, pred)
      } else {
        j = run(i, isDigit)
        if (s[j] === '.' && isDigit(s[j + 1])) j = run(j + 1, isDigit)
        if (s[j] === 'e' || s[j] === 'E') {
          let k = j + 1
          if (s[k] === '+' || s[k] === '-') k++
          if (isDigit(s[k])) j = run(k, isDigit)
        }
      }
      if (isIdPart(s[j])) bad = true
      if (bad) {
        while (j < n && isIdPart(s[j])) j++
        return fail(i, `invalid number ${s.slice(i, j).join('')}`)
      }
      push(i, 'number', s.slice(i, j).join(''))
      i = j
      continue
    }
    if (ch === '"') {
      let j = i + 1
      let v = ''
      for (;;) {
        if (j >= n) return fail(i, 'unterminated string')
        const d = s[j]
        if (d === '"') { j++; break }
        if (d === '\n') return fail(j, 'newline in string')
        if (d !== '\\') { v += d; j++; continue }
        const e = s[j + 1]
        if (e === undefined) return fail(i, 'unterminated string')
