              j = k + 1
              continue
            }
          }
        }
        return fail(j, `invalid escape \\${e}`)
      }
      push(i, 'string', JSON.stringify(v))
      i = j
      continue
    }
    const two = ch + (s[i + 1] ?? '')
    if (PUNCT2.has(two)) { push(i, 'punct', two); i += 2; continue }
    if (PUNCT1.has(ch)) { push(i, 'punct', ch); i++; continue }
    return fail(i, `unexpected character ${ch}`)
  }
  return { tokens }
}
